3: export default function pLimit(concurrency) {
4: 	let rejectOnClear = false;
5: 
6: 	if (typeof concurrency === 'object') {
7: 		({concurrency, rejectOnClear = false} = concurrency);
8: 	}
9: 
10: 	validateConcurrency(concurrency);
11: 
12: 	if (typeof rejectOnClear !== 'boolean') {
13: 		throw new TypeError('Expected `rejectOnClear` to be a boolean');
14: 	}
15: 
16: 	const queue = new Queue();
17: 	let activeCount = 0;
18: 
19: 	const resumeNext = () => {
20: 		// Process the next queued function if we're under the concurrency limit
21: 		if (activeCount < concurrency && queue.size > 0) {
22: 			activeCount++;
23: 			queue.dequeue().run();
24: 		}
25: 	};
26: 
27: 	const next = () => {
28: 		activeCount--;
29: 		resumeNext();
30: 	};
31: 
32: 	const run = async (function_, resolve, arguments_) => {
33: 		// Execute the function and capture the result promise
34: 		const result = (async () => function_(...arguments_))();
35: 
36: 		// Resolve immediately with the promise (don't wait for completion)
37: 		resolve(result);
38: 
39: 		// Wait for the function to complete (success or failure)
40: 		// We catch errors here to prevent unhandled rejections,
41: 		// but the original promise rejection is preserved for the caller
42: 		try {
43: 			await result;
44: 		} catch (error) {
45: 			next();
46: 			throw error;
47: 		}
48: 
49: 		// Decrement active count and process next queued function
50: 		next();
51: 	};
52: 
53: 	const enqueue = (function_, resolve, reject, arguments_) => {
54: 		const queueItem = {reject};
55: 
56: 		// Queue the internal resolve function instead of the run function
57: 		// to preserve the asynchronous execution context.
58: 		new Promise(internalResolve => { // eslint-disable-line promise/param-names
