60: 			queue.enqueue(queueItem);
61: 		}).then(run.bind(undefined, function_, resolve, arguments_)); // eslint-disable-line promise/prefer-await-to-then
62: 
63: 		// Start processing immediately if we haven't reached the concurrency limit
64: 		if (activeCount < concurrency) {
65: 			resumeNext();
66: 		}
67: 	};
68: 
69: 	const generator = (function_, ...arguments_) => new Promise((resolve, reject) => {
70: 		enqueue(function_, resolve, reject, arguments_);
71: 	});
72: 
73: 	Object.defineProperties(generator, {
74: 		activeCount: {
75: 			get: () => activeCount,
76: 		},
77: 		pendingCount: {
78: 			get: () => queue.size,
79: 		},
80: 		clearQueue: {
81: 			value() {
82: 				if (!rejectOnClear) {
83: 					queue.clear();
84: 					return;
85: 				}
86: 
87: 				const abortError = AbortSignal.abort().reason;
88: 
89: 				while (queue.size > 0) {
90: 					queue.dequeue().reject(abortError);
91: 				}
92: 			},
93: 		},
94: 		concurrency: {
95: 			get: () => concurrency,
96: 
97: 			set(newConcurrency) {
98: 				validateConcurrency(newConcurrency);
99: 				concurrency = newConcurrency;
100: 
101: 				queueMicrotask(() => {
102: 					// eslint-disable-next-line no-unmodified-loop-condition
103: 					while (activeCount < concurrency && queue.size > 0) {
104: 						resumeNext();
105: 					}
106: 				});
107: 			},
108: 		},
109: 		map: {
110: 			async value(iterable, function_) {
111: 				const promises = Array.from(iterable, (value, index) => generator(function_, value, index));
112: 				return Promise.all(promises);
113: 			},
114: 		},
115: 	});
116: 
117: 	return generator;
118: }
