122: 
123: 	const limitedFunction = (...arguments_) => limit(() => function_(...arguments_));
124: 	Object.defineProperty(limitedFunction, 'clearQueue', {
125: 		value: limit.clearQueue,
126: 	});
127: 
128: 	return limitedFunction;
